// Inlines the pinned maplibre-gl ESM build and map-web/page.js into a generated TypeScript module so
// the map WebView loads them from the app bundle (no CDN at runtime; works offline and in Expo Go).
// Run automatically by the npm start/typecheck/test/build pre-hooks. Output is gitignored.
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const dist = join(root, 'node_modules', 'maplibre-gl', 'dist');
const out = join(root, 'src', 'map', 'maplibreBundle.generated.ts');
const SHARED_IMPORT = '"./maplibre-gl-shared.mjs"';

const { version } = JSON.parse(readFileSync(join(root, 'node_modules', 'maplibre-gl', 'package.json'), 'utf8'));
const read = name => readFileSync(join(dist, name), 'utf8').replace(/\n\/\/# sourceMappingURL=\S+\s*$/, '\n');
const pageScript = readFileSync(join(root, 'map-web', 'page.js'), 'utf8');
if (pageScript.includes('</') || pageScript.includes('<!--')) throw new Error('map-web/page.js must not contain "</" or "<!--" (it is inlined in a <script>)');
const files = {
  MAP_PAGE_SCRIPT: pageScript,
  MAPLIBRE_MAIN: read('maplibre-gl.mjs'),
  MAPLIBRE_SHARED: read('maplibre-gl-shared.mjs'),
  MAPLIBRE_WORKER: read('maplibre-gl-worker.mjs'),
  MAPLIBRE_CSS: read('maplibre-gl.css'),
};

// The WebView rewrites exactly this specifier to a Blob URL. Fail loudly if an upgrade changes it.
for (const name of ['MAPLIBRE_MAIN', 'MAPLIBRE_WORKER']) {
  const count = files[name].split(SHARED_IMPORT).length - 1;
  if (count !== 1) throw new Error(`${name}: expected 1 import of ${SHARED_IMPORT}, found ${count}; review maplibre-gl ${version}`);
}
if (files.MAPLIBRE_SHARED.includes('from"./') || files.MAPLIBRE_SHARED.includes("from './")) {
  throw new Error(`maplibre-gl ${version}: shared chunk has relative imports the WebView cannot resolve`);
}

const body = [
  '// GENERATED by scripts/build-map-bundle.mjs from node_modules/maplibre-gl. Do not edit or commit.',
  `export const MAPLIBRE_VERSION = ${JSON.stringify(version)};`,
  `export const MAPLIBRE_SHARED_IMPORT = ${JSON.stringify(SHARED_IMPORT)};`,
  ...Object.entries(files).map(([name, text]) => `export const ${name} = ${JSON.stringify(text)};`),
  '',
].join('\n');
mkdirSync(dirname(out), { recursive: true });
writeFileSync(out, body);
console.log(`map bundle: maplibre-gl ${version} -> ${out.slice(root.length + 1)} (${Math.round(body.length / 1024)} KiB)`);
